mapper.select:
/* selectSmsRcptnTrprList (알림문자발송내역) - LeeHyeSun */ (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_VALUE = SNDNG_STTS_SE_CD AND CMMNS_CD_ID = 'SNDNG_STTS_SE_CD' ) AS SNDNG_STTS_NM , SNDNG_STTS_SE_CD , USER_NAME --발송자 , TRPR_INFO_NO --대상자정보번호 , MSG_TYPE --메세지종류(6:LMS) , REQ_DATE --즉시전송 및 예약일시(전송일시) ISRY_SMS.MSG_DATA , MSSAGE_ESNTAL_NO --메시지고유번호 , RCPTN_TRPR_NM_ENCPT --수신대상자명암호화(수신자성명) , RCPTN_MBL_TELNO_ENCPT --수신휴대전화암호화 (수신번호) , TRPR_NM_ENCPT --대상자명암호화(대상자) SEA200 , TRPR_REL_SE_CD --대상자와의관계 , RSVT_SNDNG_YN --예약발송여부 , RSVT_CHRCTR_SNDNG_DT --예약발송일시 , CALL_FROM --발신번호 , DSPTCH_TRPR_NM_ENCPT --발신자명암호화 , RSLT_CODE --결과처리상세코드 , SMS_TXT , LMS_TXT , RSVT_CHRCTR_CN , REG_YMD --등록일자 , FRST_REG_DT , UNT_TASKWK_SE_CD , FRST_RGTR_ID FROM ( SELECT CASE WHEN B.CUR_STATE = 0 THEN '00' WHEN B.CUR_STATE IN (1, 2) THEN '01' WHEN B.CUR_STATE = 3 AND B.RSLT_CODE = 100 THEN '03' WHEN B.CUR_STATE = 3 AND (B.RSLT_CODE > 100 OR B.RSLT_CODE IS NULL) THEN '02' END AS SNDNG_STTS_SE_CD , A.DSPTCH_TRPR_NM_ENCPT AS USER_NAME , A.DSPTCH_MBL_TELNO_ENCPT , A.TRPR_INFO_NO , B.MSG_TYPE , TO_CHAR(B.REQ_DATE, 'YYYY-MM-DD HH24:MI:SS') AS REQ_DATE , A.MSSAGE_ESNTAL_NO , A.RCPTN_TRPR_NM_ENCPT , A.RCPTN_MBL_TELNO_ENCPT , C.TRPR_NM_ENCPT , Z.CMMNS_CD_VALUE_NM AS TRPR_REL_SE_CD , A.RSVT_SNDNG_YN , TO_CHAR(A.RSVT_CHRCTR_SNDNG_DT, 'YYYY-MM-DD HH24:MI:SS') AS RSVT_CHRCTR_SNDNG_DT , A.DSPTCH_MBL_TELNO_ENCPT AS CALL_FROM , A.DSPTCH_TRPR_NM_ENCPT , B.CUR_STATE , B.RSLT_CODE , B.SMS_TXT , CASE WHEN MSG_TYPE = 6 THEN D.MMS_BODY ELSE '' END AS LMS_TXT , A.RSVT_CHRCTR_CN , A.REG_YMD , A.FRST_REG_DT , C.UNT_TASKWK_SE_CD , A.FRST_RGTR_ID
FROM SAB980 A /*알림문자발송*/ LEFT JOIN ISRY_SMS.MSG_LOG B ON A.MSSAGE_ESNTAL_NO = B.MSG_SEQ LEFT JOIN SEA200 C ON A.TRPR_INFO_NO = C.TRPR_INFO_NO LEFT JOIN ISRY_SMS.MMS_CONTENTS_INFO D ON B.CONT_SEQ = D.CONT_SEQ LEFT JOIN SAC100 Z /* 대상자와의관계 공통코드 */ ON Z.CMMNS_CD_ID = 'TRPR_REL_SE_CD' AND Z.CMMNS_CD_VALUE = A.TRPR_REL_SE_CD
ORDER BY FRST_REG_DT DESC ) X
WHERE 1=1 AND UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND RCPTN_TRPR_NM_ENCPT LIKE '%' || #{RCPTN_TRPR_NM_ENCPT} || '%'
AND RCPTN_MBL_TELNO_ENCPT LIKE '%' || #{RCPTN_MBL_TELNO_ENCPT} || '%'
AND REG_YMD LIKE '%' || #{REG_YMD} || '%'
AND REQ_DATE LIKE TO_CHAR(TO_DATE(#{REQ_DATE}, 'YYYY-MM-DD'), 'YYYY-MM-DD') || '%'
AND SNDNG_STTS_SE_CD = #{CMMNS_CD_VALUE}
